import React, { useEffect, useState } from 'react';

export default function Events() {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [editingEvent, setEditingEvent] = useState(null);
  const [showEditForm, setShowEditForm] = useState(false);


  const updateCount = async (id, action) => {
    try {
      const res = await fetch(`http://localhost:5000/api/events/${id}/${action}`, {
        method: 'POST'
      });
      if (!res.ok) throw new Error('Failed to update');
      const updated = await res.json();
      // Ensure events is an array before mapping
      setEvents(prevEvents => {
        const eventsArray = Array.isArray(prevEvents) ? prevEvents : [];
        return eventsArray.map(e => (e._id === id ? updated.data : e));
      });
    } catch (err) {
      setError(err.message);
    }
  };

  const handleEdit = (event) => {
    setEditingEvent(event);
    setShowEditForm(true);
  };

  const handleUpdate = async (updatedData) => {
    try {
      const res = await fetch(`http://localhost:5000/api/events/${editingEvent._id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(updatedData)
      });
      if (!res.ok) throw new Error('Failed to update event');
      const result = await res.json();

      setEvents(prevEvents => {
        const eventsArray = Array.isArray(prevEvents) ? prevEvents : [];
        return eventsArray.map(e => (e._id === editingEvent._id ? result.data : e));
      });

      setShowEditForm(false);
      setEditingEvent(null);
    } catch (err) {
      setError(err.message);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this event?')) {
      return;
    }

    try {
      const res = await fetch(`http://localhost:5000/api/events/${id}`, {
        method: 'DELETE'
      });
      if (!res.ok) throw new Error('Failed to delete event');

      setEvents(prevEvents => {
        const eventsArray = Array.isArray(prevEvents) ? prevEvents : [];
        return eventsArray.filter(e => e._id !== id);
      });
    } catch (err) {
      setError(err.message);
    }
  };

  useEffect(() => {
    fetch('http://localhost:5000/api/events')
      .then(res => {
        if (!res.ok) {
          throw new Error('Failed to fetch events');
        }
        return res.json();
      })
      .then(data => {
        // Extract events array from API response
        const eventsData = data && data.data ? data.data : [];
        setEvents(eventsData);
        setLoading(false);
      })
      .catch(err => {
        console.error('Error fetching events:', err);
        setError(err.message);
        setEvents([]); // Set to empty array on error
        setLoading(false);
      });
  }, []);

  if (loading) return <p>Loading events...</p>;
  if (error) return <p style={{ color: 'red' }}>{error}</p>;

  // Additional safety check
  if (!Array.isArray(events)) {
    console.error('Events is not an array:', events);
    return <p style={{ color: 'red' }}>Error: Events data is not properly formatted</p>;
  }

  return (
    <div className="container" style={{ padding: '40px 0' }}>
      <h2>Events</h2>

      {showEditForm && (
        <div className="card mb-4">
          <div className="card-header">
            <h5>Edit Event</h5>
          </div>
          <div className="card-body">
            <EventEditForm 
              event={editingEvent} 
              onUpdate={handleUpdate} 
              onCancel={() => {
                setShowEditForm(false);
                setEditingEvent(null);
              }} 
            />
          </div>
        </div>
      )}

      <ul className="list-group">
        {events.map(evt => (
          <li key={evt._id} className="list-group-item">
            <strong>{evt.title}</strong> ({new Date(evt.date).toLocaleString()})<br />
            Category: {evt.category} | Faculty: {evt.faculty} | Capacity: {evt.capacity}<br />
            Registrations: {evt.registrationCount} | Attendance: {evt.attendanceCount}<br />
            Status: {evt.status}
            <div style={{ marginTop: 10 }}>
              <button
                className="btn btn-sm btn-primary"
                onClick={() => updateCount(evt._id, 'register')}
              >
                +Register
              </button>{' '}
              <button
                className="btn btn-sm btn-success"
                onClick={() => updateCount(evt._id, 'checkin')}
              >
                +Check‑In
              </button>{' '}
              <button
                className="btn btn-sm btn-warning"
                onClick={() => handleEdit(evt)}
              >
                Edit
              </button>{' '}
              <button
                className="btn btn-sm btn-danger"
                onClick={() => handleDelete(evt._id)}
              >
                Delete
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

// EventEditForm Component
function EventEditForm({ event, onUpdate, onCancel }) {
  const [formData, setFormData] = useState({
    title: event.title || '',
    description: event.description || '',
    category: event.category || '',
    faculty: event.faculty || '',
    venue: event.venue || '',
    capacity: event.capacity || '',
    date: event.date ? new Date(event.date).toISOString().slice(0, 16) : '',
    status: event.status || 'Pending'
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onUpdate(formData);
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="row">
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Title</label>
            <input
              type="text"
              className="form-control"
              name="title"
              value={formData.title}
              onChange={handleChange}
              required
            />
          </div>
        </div>
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Category</label>
            <select
              className="form-control"
              name="category"
              value={formData.category}
              onChange={handleChange}
              required
            >
              <option value="">Select Category</option>
              <option value="Academic">Academic</option>
              <option value="Sports">Sports</option>
              <option value="Cultural">Cultural</option>
              <option value="Technical">Technical</option>
              <option value="Workshop">Workshop</option>
              <option value="Seminar">Seminar</option>
            </select>
          </div>
        </div>
      </div>

      <div className="row">
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Faculty</label>
            <select
              className="form-control"
              name="faculty"
              value={formData.faculty}
              onChange={handleChange}
              required
            >
              <option value="">Select Faculty</option>
              <option value="Computing">Computing</option>
              <option value="Engineering">Engineering</option>
              <option value="Business">Business</option>
              <option value="Science">Science</option>
              <option value="Architecture">Architecture</option>
              <option value="Graduate Studies">Graduate Studies</option>
            </select>
          </div>
        </div>
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Venue</label>
            <input
              type="text"
              className="form-control"
              name="venue"
              value={formData.venue}
              onChange={handleChange}
            />
          </div>
        </div>
      </div>

      <div className="row">
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Capacity</label>
            <input
              type="number"
              className="form-control"
              name="capacity"
              value={formData.capacity}
              onChange={handleChange}
              min="1"
              required
            />
          </div>
        </div>
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Date & Time</label>
            <input
              type="datetime-local"
              className="form-control"
              name="date"
              value={formData.date}
              onChange={handleChange}
              required
            />
          </div>
        </div>
      </div>

      <div className="row">
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Status</label>
            <select
              className="form-control"
              name="status"
              value={formData.status}
              onChange={handleChange}
            >
              <option value="Pending">Pending</option>
              <option value="Approved">Approved</option>
              <option value="Rejected">Rejected</option>
              <option value="Cancelled">Cancelled</option>
              <option value="Completed">Completed</option>
            </select>
          </div>
        </div>
      </div>

      <div className="form-group mb-3">
        <label className="form-label">Description</label>
        <textarea
          className="form-control"
          name="description"
          value={formData.description}
          onChange={handleChange}
          rows="3"
        />
      </div>

      <div className="d-flex gap-2">
        <button type="submit" className="btn btn-primary">
          Update Event
        </button>
        <button type="button" className="btn btn-secondary" onClick={onCancel}>
          Cancel
        </button>
      </div>
    </form>
  );
}
